import {
  closestCenter,
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useDraggable,
  useDroppable,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable"
import {
  ArrowDown01Icon,
  AttachmentIcon,
  Calendar03Icon,
  CheckListIcon,
  Copy01Icon,
  Delete02Icon,
  DragDropVerticalIcon,
  HashtagIcon,
  Heading01Icon,
  HierarchySquare01Icon,
  Image01Icon,
  InputLongTextIcon,
  InputShortTextIcon,
  Layout01Icon,
  Note01Icon,
  PlusSignIcon,
  RadioButtonIcon,
  RepeatIcon,
  Search01Icon,
  SectionIcon,
  UserCircleIcon,
  UserIcon,
} from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"
import { useForm } from "@tanstack/react-form"
import { Badge } from "@workspace/ui/components/badge"
import { Button } from "@workspace/ui/components/button"
import { Input } from "@workspace/ui/components/input"
import { Label } from "@workspace/ui/components/label"
import { NumberField } from "@workspace/ui/components/number-field"
import { ScrollArea } from "@workspace/ui/components/scroll-area"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@workspace/ui/components/select"
import { Separator } from "@workspace/ui/components/separator"
import {
  SortableItem,
  SortableItemHandle,
} from "@workspace/ui/components/sortable"
import { Switch } from "@workspace/ui/components/switch"
import { Textarea } from "@workspace/ui/components/textarea"
import { cn } from "@workspace/ui/lib/utils"
import { useEffect, useMemo, useState, type ReactNode } from "react"

import {
  CONTEXT_BINDING_LABELS,
  CONTEXT_BINDINGS,
  collectKeys,
  createEmptyForm,
  defaultNodeForKind,
  duplicateNode,
  encodeMarkerPlaceholder,
  encodeValuePlaceholder,
  findNode,
  flattenChoiceOptions,
  FORM_LAYOUT_KIND_LABELS,
  FORM_QUESTION_KIND_LABELS,
  FORM_TAG_MIME,
  addPage,
  insertExistingNode,
  isChoiceKind,
  isContextBinding,
  isLayoutBlock,
  isLayoutKind,
  isQuestion,
  isQuestionKind,
  moveNode,
  parseFlatOptions,
  parseOptionTree,
  removeNode,
  removePage,
  renameForm,
  serializeOptionTree,
  slugifyKey,
  tagsFromForm,
  updateNode,
  updatePage,
  visibilitySourceQuestions,
  type BoundTag,
  type ContextBinding,
  type FormConditionGroup,
  type FormConditionOp,
  type FormNode,
  type FormNodeKind,
  type FormNodePatch,
  type FormPage,
  type FormQuestion,
  type FormTemplate,
} from "../index"
import { FieldPreview } from "./field-preview"

const CANVAS_ID = "form-canvas"

type PaletteItem = Readonly<{
  kind: FormNodeKind
  label: string
  icon: typeof InputShortTextIcon
}>

const QUESTION_PALETTE: readonly PaletteItem[] = [
  { kind: "short_text", label: "Short text", icon: InputShortTextIcon },
  { kind: "long_text", label: "Long text", icon: InputLongTextIcon },
  { kind: "number", label: "Number", icon: HashtagIcon },
  { kind: "date", label: "Date", icon: Calendar03Icon },
  { kind: "boolean", label: "Yes / No", icon: RadioButtonIcon },
  { kind: "select", label: "Select", icon: ArrowDown01Icon },
  { kind: "multi_select", label: "Multi-select", icon: CheckListIcon },
  { kind: "autocomplete", label: "Autocomplete", icon: Search01Icon },
  { kind: "cascader", label: "Cascader", icon: HierarchySquare01Icon },
  { kind: "reference", label: "Reference", icon: UserIcon },
  { kind: "attachment", label: "Attachment", icon: AttachmentIcon },
  { kind: "repeater", label: "Repeater", icon: RepeatIcon },
  { kind: "context", label: "Context", icon: UserCircleIcon },
]

const LAYOUT_PALETTE: readonly PaletteItem[] = [
  { kind: "section", label: "Section", icon: SectionIcon },
  { kind: "heading", label: "Heading", icon: Heading01Icon },
  { kind: "text", label: "Text", icon: Note01Icon },
  { kind: "image", label: "Image", icon: Image01Icon },
]

const PALETTE_ITEMS = [...QUESTION_PALETTE, ...LAYOUT_PALETTE]

const CONDITION_OPS: readonly Readonly<{ op: FormConditionOp; label: string }>[] = [
  { op: "eq", label: "is" },
  { op: "neq", label: "is not" },
  { op: "in", label: "is one of" },
  { op: "not_in", label: "is not one of" },
  { op: "is_set", label: "is answered" },
  { op: "is_empty", label: "is empty" },
  { op: "gt", label: "is greater than" },
  { op: "lt", label: "is less than" },
]

function paletteDragId(kind: FormNodeKind): string {
  return `palette:${kind}`
}

function parentDropId(id: string): string {
  return `parent:${id}`
}

function kindFromPaletteId(id: string): FormNodeKind | null {
  if (!id.startsWith("palette:")) return null
  const kind = id.slice("palette:".length)
  return PALETTE_ITEMS.find((item) => item.kind === kind)?.kind ?? null
}

function labelForKind(kind: FormNodeKind): string {
  if (isQuestionKind(kind)) return FORM_QUESTION_KIND_LABELS[kind]
  if (isLayoutKind(kind)) return FORM_LAYOUT_KIND_LABELS[kind]
  return kind
}

export type FormBuilderProps = Readonly<{
  form: FormTemplate
  onFormChange: (form: FormTemplate) => void
  selectedNodeId?: string | null
  onSelectedNodeIdChange?: (id: string | null) => void
}>

export function FormBuilder({
  form,
  onFormChange,
  selectedNodeId: selectedNodeIdProp,
  onSelectedNodeIdChange,
}: FormBuilderProps): ReactNode {
  const [internalSelected, setInternalSelected] = useState<string | null>(null)
  const selectedNodeId = selectedNodeIdProp ?? internalSelected
  const setSelectedNodeId = (id: string | null) => {
    onSelectedNodeIdChange?.(id)
    if (selectedNodeIdProp === undefined) setInternalSelected(id)
  }
  const [pageId, setPageId] = useState(form.pages[0]?.id ?? "")
  const [activeDrag, setActiveDrag] = useState<
    Readonly<{ type: "palette"; kind: FormNodeKind } | { type: "node"; id: string }> | null
  >(null)
  const page = form.pages.find((entry) => entry.id === pageId) ?? form.pages[0]
  const tags = useMemo(() => tagsFromForm(form), [form])
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  useEffect(() => {
    if (!form.pages.some((entry) => entry.id === pageId)) {
      setPageId(form.pages[0]?.id ?? "")
    }
  }, [form.pages, pageId])

  const insertKind = (
    kind: FormNodeKind,
    target: Readonly<{ pageId: string; index: number; parentId: string | null }>
  ) => {
    const node = defaultNodeForKind(kind, labelForKind(kind), collectKeys(form))
    onFormChange(
      insertExistingNode(form, target.pageId, node, {
        index: target.index,
        parentId: target.parentId,
      })
    )
    setSelectedNodeId(node.id)
  }

  const onDragStart = (event: DragStartEvent) => {
    const kind = kindFromPaletteId(String(event.active.id))
    if (kind) {
      setActiveDrag({ type: "palette", kind })
      return
    }
    setActiveDrag({ type: "node", id: String(event.active.id) })
  }

  const onDragEnd = (event: DragEndEvent) => {
    setActiveDrag(null)
    const overId = event.over ? String(event.over.id) : null
    const activeId = String(event.active.id)
    if (!page) return
    const paletteKind = kindFromPaletteId(activeId)
    if (paletteKind) {
      const target = resolveDrop(overId, form, page)
      if (!target) return
      insertKind(paletteKind, target)
      return
    }
    if (!overId || activeId === overId) return
    const target = resolveDrop(overId, form, page)
    if (!target || target.parentId === activeId) return
    onFormChange(
      moveNode(form, activeId, {
        pageId: target.pageId,
        index: target.index,
        parentId: target.parentId,
      })
    )
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={onDragStart}
      onDragCancel={() => setActiveDrag(null)}
      onDragEnd={onDragEnd}
    >
      <div className="apex-form-builder">
        <FieldPalette
          onAdd={(kind) => {
            if (!page) return
            insertKind(kind, {
              pageId: page.id,
              index: page.nodes.length,
              parentId: null,
            })
          }}
        />
        <FormCanvas
          form={form}
          page={page}
          selectedNodeId={selectedNodeId}
          onPageIdChange={setPageId}
          onSelect={setSelectedNodeId}
          onAddPage={() => {
            const next = addPage(form)
            const created = next.pages[next.pages.length - 1]
            onFormChange(next)
            if (created) setPageId(created.id)
            setSelectedNodeId(null)
          }}
          onRemove={(id) => {
            onFormChange(removeNode(form, id))
            if (selectedNodeId === id) setSelectedNodeId(null)
          }}
          onDuplicate={(id) => {
            const next = duplicateNode(form, id)
            onFormChange(next)
            const added = newestNodeId(form, next)
            if (added) setSelectedNodeId(added)
          }}
        />
        <SettingsPanel
          form={form}
          page={page}
          selectedNodeId={selectedNodeId}
          tags={tags}
          onFormChange={onFormChange}
          onDuplicate={(id) => {
            const next = duplicateNode(form, id)
            onFormChange(next)
            const added = newestNodeId(form, next)
            if (added) setSelectedNodeId(added)
          }}
          onRemove={(id) => {
            onFormChange(removeNode(form, id))
            if (selectedNodeId === id) setSelectedNodeId(null)
          }}
          onRemovePage={(id) => {
            onFormChange(removePage(form, id))
            setSelectedNodeId(null)
          }}
        />
      </div>
      <DragOverlay dropAnimation={null}>
        {activeDrag?.type === "palette" ? (
          <PaletteChipFace item={paletteItemForKind(activeDrag.kind)} dragging />
        ) : activeDrag?.type === "node" ? (
          <div className="rounded-lg border bg-background px-3 py-2 text-sm shadow-md">
            {findNode(form, activeDrag.id)?.node.label ?? "Question"}
          </div>
        ) : null}
      </DragOverlay>
    </DndContext>
  )
}

function FieldPalette({
  onAdd,
}: Readonly<{ onAdd: (kind: FormNodeKind) => void }>): ReactNode {
  return (
    <aside className="flex h-full w-[240px] shrink-0 flex-col border-r bg-background">
      <div className="p-3">
        <p className="text-sm font-medium">Questions</p>
      </div>
      <ScrollArea className="min-h-0 flex-1">
        <div className="flex flex-col gap-4 p-3 pt-0">
          <PaletteGroup title="Fields" items={QUESTION_PALETTE} onAdd={onAdd} />
          <PaletteGroup title="Layout" items={LAYOUT_PALETTE} onAdd={onAdd} />
        </div>
      </ScrollArea>
    </aside>
  )
}

function PaletteGroup({
  title,
  items,
  onAdd,
}: Readonly<{
  title: string
  items: readonly PaletteItem[]
  onAdd: (kind: FormNodeKind) => void
}>): ReactNode {
  return (
    <div className="flex flex-col gap-1.5">
      <p className="text-[11px] font-medium tracking-wide text-muted-foreground uppercase">
        {title}
      </p>
      <div className="grid grid-cols-1 gap-1">
        {items.map((item) => (
          <PaletteChip key={item.kind} item={item} onAdd={onAdd} />
        ))}
      </div>
    </div>
  )
}

function PaletteChipFace({
  item,
  dragging = false,
}: Readonly<{ item: PaletteItem; dragging?: boolean }>): ReactNode {
  return (
    <div
      className={cn(
        "flex w-full items-center gap-2 rounded-lg border bg-background px-2 py-1.5 text-left text-sm",
        dragging && "shadow-md"
      )}
    >
      <HugeiconsIcon icon={item.icon} strokeWidth={2} className="size-4 text-muted-foreground" />
      <span className="truncate">{item.label}</span>
    </div>
  )
}

function PaletteChip({
  item,
  onAdd,
}: Readonly<{
  item: PaletteItem
  onAdd: (kind: FormNodeKind) => void
}>): ReactNode {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: paletteDragId(item.kind),
    data: { type: "palette", kind: item.kind },
  })
  return (
    <button
      ref={setNodeRef}
      type="button"
      className={cn("w-full hover:bg-muted", isDragging && "opacity-50")}
      {...attributes}
      {...listeners}
      onClick={() => {
        if (isDragging) return
        onAdd(item.kind)
      }}
    >
      <PaletteChipFace item={item} />
    </button>
  )
}

function FormCanvas({
  form,
  page,
  selectedNodeId,
  onPageIdChange,
  onSelect,
  onAddPage,
  onRemove,
  onDuplicate,
}: Readonly<{
  form: FormTemplate
  page: FormPage | undefined
  selectedNodeId: string | null
  onPageIdChange: (id: string) => void
  onSelect: (id: string | null) => void
  onAddPage: () => void
  onRemove: (id: string) => void
  onDuplicate: (id: string) => void
}>): ReactNode {
  const { setNodeRef, isOver } = useDroppable({ id: CANVAS_ID })
  const nodes = page?.nodes ?? []
  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col bg-muted/40">
      <div className="flex items-center gap-2 overflow-x-auto border-b bg-background px-3 py-2">
        {form.pages.map((entry, index) => (
          <Button
            key={entry.id}
            type="button"
            size="sm"
            variant={entry.id === page?.id ? "secondary" : "ghost"}
            onClick={() => {
              onPageIdChange(entry.id)
              onSelect(null)
            }}
          >
            {entry.title || `Page ${index + 1}`}
          </Button>
        ))}
        <Button type="button" size="icon-sm" variant="ghost" aria-label="Add page" onClick={onAddPage}>
          <HugeiconsIcon icon={PlusSignIcon} strokeWidth={2} />
        </Button>
      </div>
      <ScrollArea className="h-full min-h-0 flex-1">
        <div className="relative flex min-h-full justify-center p-6">
          <button
            type="button"
            className="absolute inset-0"
            aria-label="Clear question selection"
            onClick={() => onSelect(null)}
          />
          <div
            ref={setNodeRef}
            className={cn(
              "relative z-10 flex min-h-full w-full max-w-xl flex-col rounded-xl border bg-background p-6 shadow-sm",
              isOver && nodes.length === 0 && "ring-2 ring-primary/40"
            )}
          >
            <div className="mb-6">
              <h2 className="text-lg font-medium">{form.name}</h2>
              {page?.description ? (
                <p className="mt-1 text-sm text-muted-foreground">{page.description}</p>
              ) : (
                <p className="mt-1 text-sm text-muted-foreground">
                  {page?.title || "Form preview"}
                </p>
              )}
            </div>
            {nodes.length === 0 ? (
              <div className="flex min-h-48 flex-1 flex-col items-center justify-center rounded-lg border border-dashed p-8 text-center">
                <HugeiconsIcon icon={Layout01Icon} strokeWidth={2} className="mb-2 size-6 text-muted-foreground" />
                <p className="text-sm font-medium">Drag a question here</p>
              </div>
            ) : (
              <SortableContext
                items={nodes.map((node) => node.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="flex flex-col gap-3">
                  {nodes.map((node) => (
                    <SortablePreviewCard
                      key={node.id}
                      node={node}
                      selectedNodeId={selectedNodeId}
                      onSelect={onSelect}
                      onRemove={onRemove}
                      onDuplicate={onDuplicate}
                    />
                  ))}
                </div>
              </SortableContext>
            )}
          </div>
        </div>
      </ScrollArea>
    </div>
  )
}

function SortablePreviewCard({
  node,
  selectedNodeId,
  onSelect,
  onRemove,
  onDuplicate,
}: Readonly<{
  node: FormNode
  selectedNodeId: string | null
  onSelect: (id: string) => void
  onRemove: (id: string) => void
  onDuplicate: (id: string) => void
}>): ReactNode {
  const selected = node.id === selectedNodeId
  const isRepeater = isQuestion(node) && node.kind === "repeater"
  return (
    <SortableItem value={node.id}>
      <div
        className={cn(
          "group/card relative rounded-lg border bg-background p-3 transition-colors",
          selected
            ? "border-primary ring-2 ring-primary/20"
            : "hover:border-foreground/20"
        )}
      >
        <div className="mb-2 flex items-center gap-1">
          <SortableItemHandle
            className="text-muted-foreground hover:text-foreground"
            aria-label={`Reorder ${node.label}`}
          >
            <HugeiconsIcon icon={DragDropVerticalIcon} strokeWidth={2} className="size-4" />
          </SortableItemHandle>
          <button
            type="button"
            className="text-[11px] tracking-wide text-muted-foreground uppercase"
            onClick={() => onSelect(node.id)}
          >
            {labelForKind(node.kind)}
          </button>
          {node.condition && node.condition.rules.length > 0 ? (
            <Badge variant="outline" className="text-[10px]">
              Conditional
            </Badge>
          ) : null}
          <div
            className={cn(
              "ml-auto items-center gap-0.5",
              selected ? "flex" : "hidden group-hover/card:flex"
            )}
          >
            <Button
              type="button"
              size="icon-xs"
              variant="ghost"
              aria-label={`Duplicate ${node.label}`}
              onClick={(event) => {
                event.stopPropagation()
                onDuplicate(node.id)
              }}
            >
              <HugeiconsIcon icon={Copy01Icon} strokeWidth={2} />
            </Button>
            <Button
              type="button"
              size="icon-xs"
              variant="ghost"
              aria-label={`Delete ${node.label}`}
              onClick={(event) => {
                event.stopPropagation()
                onRemove(node.id)
              }}
            >
              <HugeiconsIcon icon={Delete02Icon} strokeWidth={2} />
            </Button>
          </div>
        </div>
        {isRepeater && isQuestion(node) ? (
          <RepeaterPreview
            node={node}
            selectedNodeId={selectedNodeId}
            onSelect={onSelect}
            onRemove={onRemove}
          />
        ) : (
          <button type="button" className="w-full text-left" onClick={() => onSelect(node.id)}>
            <FieldPreview node={node} />
          </button>
        )}
      </div>
    </SortableItem>
  )
}

function RepeaterPreview({
  node,
  selectedNodeId,
  onSelect,
  onRemove,
}: Readonly<{
  node: FormNode
  selectedNodeId: string | null
  onSelect: (id: string) => void
  onRemove: (id: string) => void
}>): ReactNode {
  const children = isQuestion(node) ? (node.children ?? []) : []
  const { setNodeRef, isOver } = useDroppable({ id: parentDropId(node.id) })
  return (
    <div className="flex flex-col gap-2">
      <button type="button" className="w-full text-left" onClick={() => onSelect(node.id)}>
        <LabeledName label={node.label} required={isQuestion(node) ? node.required : false} />
      </button>
      <div
        ref={setNodeRef}
        className={cn(
          "flex flex-col gap-2 rounded-lg border border-dashed p-3",
          isOver && "border-primary bg-primary/5"
        )}
      >
        {children.length === 0 ? (
          <p className="py-4 text-center text-xs text-muted-foreground">
            Drop questions here to repeat them for each row.
          </p>
        ) : (
          children.map((child) => (
            <div
              key={child.id}
              className={cn(
                "rounded-md border bg-background p-2",
                child.id === selectedNodeId && "border-primary ring-2 ring-primary/20"
              )}
            >
              <div className="mb-1 flex items-center justify-between gap-2">
                <button
                  type="button"
                  className="text-[11px] text-muted-foreground uppercase"
                  onClick={() => onSelect(child.id)}
                >
                  {labelForKind(child.kind)}
                </button>
                <Button
                  type="button"
                  size="icon-xs"
                  variant="ghost"
                  aria-label={`Delete ${child.label}`}
                  onClick={(event) => {
                    event.stopPropagation()
                    onRemove(child.id)
                  }}
                >
                  <HugeiconsIcon icon={Delete02Icon} strokeWidth={2} />
                </Button>
              </div>
              <button type="button" className="w-full text-left" onClick={() => onSelect(child.id)}>
                <FieldPreview node={child} />
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  )
}

function LabeledName({
  label,
  required,
}: Readonly<{ label: string; required: boolean }>): ReactNode {
  return (
    <p className="text-sm font-medium">
      {label}
      {required ? <span className="text-destructive"> *</span> : null}
    </p>
  )
}

function SettingsPanel({
  form,
  page,
  selectedNodeId,
  tags,
  onFormChange,
  onDuplicate,
  onRemove,
  onRemovePage,
}: Readonly<{
  form: FormTemplate
  page: FormPage | undefined
  selectedNodeId: string | null
  tags: readonly BoundTag[]
  onFormChange: (form: FormTemplate) => void
  onDuplicate: (id: string) => void
  onRemove: (id: string) => void
  onRemovePage: (id: string) => void
}>): ReactNode {
  const node = selectedNodeId ? (findNode(form, selectedNodeId)?.node ?? null) : null
  return (
    <aside className="flex h-full w-[300px] shrink-0 flex-col border-l bg-background">
      <div className="flex items-start justify-between gap-2 border-b p-3">
        <div>
          <p className="text-sm font-medium">{node ? "Question settings" : "Form settings"}</p>
          <p className="text-xs text-muted-foreground">
            {node ? labelForKind(node.kind) : page?.title || form.name}
          </p>
        </div>
        {node ? (
          <div className="flex items-center">
            <Button
              type="button"
              size="icon-xs"
              variant="ghost"
              aria-label={`Duplicate ${node.label}`}
              onClick={() => onDuplicate(node.id)}
            >
              <HugeiconsIcon icon={Copy01Icon} strokeWidth={2} />
            </Button>
            <Button
              type="button"
              size="icon-xs"
              variant="ghost"
              aria-label={`Delete ${node.label}`}
              onClick={() => onRemove(node.id)}
            >
              <HugeiconsIcon icon={Delete02Icon} strokeWidth={2} />
            </Button>
          </div>
        ) : null}
      </div>
      <ScrollArea className="min-h-0 flex-1">
        <div className="flex flex-col gap-5 p-3">
          {!node && page ? (
            <FormSettings
              form={form}
              page={page}
              onFormChange={onFormChange}
              onRemovePage={onRemovePage}
            />
          ) : null}
          {node ? (
            <NodeInspector
              key={node.id}
              node={node}
              sources={visibilitySourceQuestions(form).filter(
                (question) => question.id !== node.id
              )}
              onChange={(patch) => onFormChange(updateNode(form, node.id, patch))}
            />
          ) : null}
          <Separator />
          <div className="flex flex-col gap-2">
            <p className="text-[11px] font-medium tracking-wide text-muted-foreground uppercase">
              Document tags
            </p>
            <p className="text-xs text-muted-foreground">
              Drag a tag into the document to bind this form.
            </p>
            {tags.length === 0 ? (
              <p className="text-xs text-muted-foreground">No bindable questions yet.</p>
            ) : (
              tags.map((tag) => <TagBadge key={tag.id} tag={tag} />)
            )}
          </div>
