function TagBadge({ tag }: Readonly<{ tag: BoundTag }>): ReactNode {
  const placeholder =
    tag.role === "value"
      ? encodeValuePlaceholder(tag)
      : tag.role === "each"
        ? encodeMarkerPlaceholder({ type: "each", path: tag.slug })
        : tag.role === "if"
          ? encodeMarkerPlaceholder({ type: "if", path: tag.slug })
          : `{{@image ${tag.slug}}}`
  return (
    <button
      type="button"
      draggable
      className="flex w-full items-center justify-between gap-2 rounded-md border px-2 py-1.5 text-left text-sm"
      onDragStart={(event) => {
        event.dataTransfer.setData(FORM_TAG_MIME, tag.id)
        event.dataTransfer.setData("text/plain", placeholder)
        event.dataTransfer.effectAllowed = "copy"
      }}
    >
      <span className="truncate">{tag.label}</span>
      <Badge variant="outline">{tag.role}</Badge>
    </button>
  )
}

function resolveDrop(
  overId: string | null,
  form: FormTemplate,
  page: FormPage
): Readonly<{ pageId: string; index: number; parentId: string | null }> | null {
  if (!overId) return null
  if (kindFromPaletteId(overId)) return null
  if (overId === CANVAS_ID) {
    return { pageId: page.id, index: page.nodes.length, parentId: null }
  }
  if (overId.startsWith("parent:")) {
    const parentId = overId.slice("parent:".length)
    const located = findNode(form, parentId)
    if (!located || !isQuestion(located.node)) return null
    return {
      pageId: located.location.pageId,
      index: located.node.children?.length ?? 0,
      parentId,
    }
  }
  const located = findNode(form, overId)
  if (!located) return null
  return {
    pageId: located.location.pageId,
    index: located.location.index,
    parentId: located.location.parentId,
  }
}

function paletteItemForKind(kind: FormNodeKind): PaletteItem {
  return (
    PALETTE_ITEMS.find((item) => item.kind === kind) ?? {
      kind,
      label: labelForKind(kind),
      icon: Layout01Icon,
    }
  )
}

function newestNodeId(before: FormTemplate, after: FormTemplate): string | null {
  const previous = new Set<string>()
  for (const page of before.pages) collectIds(page.nodes, previous)
  for (const page of after.pages) {
    const found = firstNewId(page.nodes, previous)
    if (found) return found
  }
  return null
}

function collectIds(nodes: readonly FormNode[], into: Set<string>): void {
  for (const node of nodes) {
    into.add(node.id)
    if (isQuestion(node) && node.children) collectIds(node.children, into)
  }
}

function firstNewId(nodes: readonly FormNode[], previous: Set<string>): string | null {
  for (const node of nodes) {
    if (!previous.has(node.id)) return node.id
    if (isQuestion(node) && node.children) {
      const nested = firstNewId(node.children, previous)
      if (nested) return nested
    }
  }
  return null
}

