    >
      <QuestionPreview question={node} />
    </LabeledPreview>
  )
}

function QuestionPreview({
  question,
}: Readonly<{ question: FormQuestion }>): ReactNode {
  switch (question.kind) {
    case "short_text":
      return <Input disabled placeholder="Your answer" />
    case "long_text":
      return <Textarea disabled placeholder="Your answer" />
    case "number":
      return <NumberField disabled value={null} onValueChange={() => undefined} />
    case "date":
      return (
        <DatePicker
          value=""
          includeTime={question.includeTime === true}
          disabled
          onValueChange={() => undefined}
        />
      )
    case "boolean":
      return (
        <RadioGroup disabled value="" className="flex gap-4">
          <div className="flex items-center gap-2 text-sm">
            <RadioGroupItem value="yes" />
            Yes
          </div>
          <div className="flex items-center gap-2 text-sm">
            <RadioGroupItem value="no" />
            No
          </div>
        </RadioGroup>
      )
    case "select":
      return (
        <div className="flex h-8 w-full items-center justify-between rounded-lg border border-input px-2.5 text-sm text-muted-foreground">
          {(question.options ?? [])[0]?.label ?? "Select…"}
        </div>
      )
    case "autocomplete":
      return (
        <AutocompleteField
          disabled
          options={question.options ?? []}
          value=""
          placeholder="Search…"
          onValueChange={() => undefined}
        />
      )
    case "cascader":
      return (
        <Cascader
          disabled
          options={question.options ?? []}
          value=""
          placeholder="Select…"
          onValueChange={() => undefined}
        />
      )
    case "multi_select":
      return (
        <div className="flex flex-col gap-2">
          {(question.options ?? []).map((option) => (
            <div key={option.value} className="flex items-center gap-2 text-sm">
              <Checkbox disabled />
              {option.label}
            </div>
          ))}
          {question.allowOther ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Checkbox disabled />
              Other
            </div>
          ) : null}
        </div>
      )
    case "reference":
      return (
        <div className="flex h-8 w-full items-center justify-between rounded-lg border border-input px-2.5 text-sm text-muted-foreground">
          Search {question.reference?.source ?? "record"}…
        </div>
      )
    case "attachment":
      return <Input type="file" disabled />
    case "context": {
      const binding = question.context?.binding
      return (
        <Input
          disabled
          value={
            binding ? CONTEXT_BINDING_LABELS[binding] : "Context value"
          }
        />
      )
    }
    default:
      return null
  }
}

function LabeledPreview({
  label,
  description,
  required,
  children,
}: Readonly<{
  label: string
  description?: string
  required?: boolean
  children: ReactNode
}>): ReactNode {
  return (
    <div className="flex flex-col gap-1.5">
      <Label>
        {label}
        {required ? <span className="text-destructive"> *</span> : null}
      </Label>
      {description ? (
        <p className="text-xs text-muted-foreground">{description}</p>
      ) : null}
      <div className="pointer-events-none">{children}</div>
    </div>
  )
}
